<script setup lang="ts">import {computed,onMounted,ref,watch} from 'vue'; import {useRoute} from 'vue-router'; import {api} from '../api'; const route=useRoute(); const rows=ref<any[]>([]); const loading=ref(false); const resource=computed(()=>String(route.params.resource)); const labels:Record<string,string>={standards:'食材标准库',suppliers:'供应商',plans:'采购计划',inquiries:'询价/竞价',orders:'采购订单',deliveries:'配送',inspections:'智能验收',inventory:'库存批次',settlements:'结算'}; async function load(){loading.value=true;try{rows.value=(await api.get('/'+resource.value)).data}finally{loading.value=false}} onMounted(load);watch(resource,load);</script><template><div class="bar"><h1>{{labels[resource]||resource}}</h1><el-button type="primary" @click="$router.push('/')">返回驾驶舱</el-button></div><el-alert title="MVP 当前提供业务列表与 API 写入能力；创建/审批工作流可在 OpenAPI 中调用。" type="info" :closable="false"/><el-table :data="rows" v-loading="loading" stripe style="margin-top:16px"><el-table-column v-for="key in (rows[0]?Object.keys(rows[0]):['id'])" :key="key" :prop="key" :label="key" min-width="150"/></el-table></template><style scoped>.bar{display:flex;justify-content:space-between;align-items:center}</style>
